import test from 'node:test';import assert from 'node:assert/strict';
import {EMAIL,EMAIL_REPAIRED_FILES} from './email-repair-source.mjs';
import {createEmailInstallGrant} from './email-install-grant.mjs';
import {inspectEmailRepairBuildOnlySnapshot} from './build-only-evidence.mjs';
import {installationFixture} from './staging-install-test-fixture.mjs';
import {REPOSITORY,REPOSITORY_ID,WORKFLOW_ID,WORKFLOW_PATH} from './release-policy.mjs';
import {BUILD_ARTIFACT} from './build-artifact.mjs';
import {installHash,installJson} from './ci-install-grant.mjs';
function fixture(){
 const f=installationFixture(),created=new Date(f.now-2000).toISOString(),started=new Date(f.now-1500).toISOString(),ended=new Date(f.now-500).toISOString();
 const run={id:EMAIL.buildRun,repository:{id:REPOSITORY_ID,full_name:REPOSITORY},head_repository:{id:REPOSITORY_ID},workflow_id:WORKFLOW_ID,path:WORKFLOW_PATH,head_sha:EMAIL.buildController,head_branch:'alpha',event:'workflow_dispatch',status:'completed',conclusion:'success',run_attempt:1,created_at:created,updated_at:ended};
 const active=['resolve','build','deployment-hold'],skipped=['typecheck','migrations','runner-diagnostics','controller-tests','plan','test','browser','verify'];
 const jobs=[...active,...skipped].map((name,i)=>({id:i+1,name,run_id:run.id,run_attempt:1,head_sha:run.head_sha,head_branch:'alpha',status:'completed',conclusion:active.includes(name)?'success':'skipped',started_at:started,completed_at:ended,steps:name==='resolve'?[{name:'Refuse invalid build-only execution',conclusion:'success'}]:name==='build'?[{name:'Canonical System Testing production build and byte bundle',conclusion:'success'},{name:'Publish mandatory canonical build packet',conclusion:'success'}]:[]}));
 const artifact={id:1,name:BUILD_ARTIFACT,digest:'sha256:'+'a'.repeat(64),expired:false,size_in_bytes:100,created_at:ended,expires_at:new Date(f.now+86400000).toISOString(),workflow_run:{id:run.id,repository_id:REPOSITORY_ID,head_repository_id:REPOSITORY_ID,head_sha:run.head_sha,head_branch:'alpha'}};
 const row=path=>({path,state:'PASSED',passingAssertions:1,failedAssertions:0,originCandidate:EMAIL.original});
 const ordinaryFiles=[...EMAIL_REPAIRED_FILES.map(path=>({...row(path),originCandidate:EMAIL.candidate,origin:{runId:EMAIL.repairRun}})),...Array.from({length:2039},(_,i)=>row('test/unchanged-'+i+'.test.ts'))];
 const browserFiles=['chromium','firefox','webkit'].flatMap(engine=>Array.from({length:20},(_,i)=>({...row('test/page-'+i+'.browser.test.tsx'),engine})));
 const body={kind:'COMBINED_EMAIL_FULL_RUN_AND_TEST_CONTRACT_REPAIR',policy:'email-test-contract-repair/v1',result:'ACCEPTED_WITH_AUTHENTICATED_ORIGINAL_PASSES',candidate:EMAIL.candidate,original:EMAIL.original,originalRun:{runId:EMAIL.fullRun,conclusion:'failure'},originalFailures:EMAIL_REPAIRED_FILES.map(path=>({path})),ordinaryFiles,browserFiles,wholeCompiler:{kind:'AUTHENTICATED_EMAIL_REPAIR_WHOLE_COMPILER',candidate:EMAIL.candidate,controller:EMAIL.compilerController,runId:EMAIL.compilerRun,conclusion:'success',runtime:{node:'22.23.3',platform:'linux',arch:'x64'}},sourceProofSha256:'f'.repeat(64),fullGatePassCreated:false,createsNewFullPassBaseline:false,releaseAuthorized:false,postDeployAcceptanceRequired:true};
 const acceptance={...body,acceptanceSha256:installHash(installJson(body))},boundary={kind:'FORWARD_STAGING_BASELINE_SOURCE_PREFIX_NOT_CI_RECEIPT',candidate:EMAIL.candidate,ciBaseline:EMAIL.ciBaseline,deploymentBaseline:EMAIL.bonus,ciMigrationCount:498,deploymentMigrationCount:503,candidateMigrationCount:504,originalCiBaselinePreserved:true,requiresFreshActualLedgerAndBuildBinding:true,releaseAuthorized:false};
 const evidence={kind:'AUTHENTICATED_EMAIL_TEST_REPAIR_AND_CANONICAL_BUILD',sha:EMAIL.candidate,controller:EMAIL.buildController,controllerBranch:'alpha',runId:EMAIL.buildRun,baseline:EMAIL.ciBaseline,deploymentBaseline:EMAIL.bonus,artifact:{id:artifact.id,digest:artifact.digest},build:{...f.evidence.build,canonicalCandidateInputsVerified:true,source:EMAIL.candidate,controller:EMAIL.buildController,runId:EMAIL.buildRun},baselineAdvance:{...boundary,proofSha256:installHash(installJson(boundary))}};
 return {...f,acceptance,evidence,snapshot:{run,jobs,artifacts:[artifact]}};
}
test('actual combined coverage yields an ordinary bounded native grant without claiming a full PASS',()=>{const f=fixture(),g=createEmailInstallGrant(f);assert.equal(g.source,EMAIL.candidate);assert.equal(g.baseline,EMAIL.bonus);assert.equal(g.controller,EMAIL.buildController);assert.equal(g.result,undefined);assert.notEqual(g.witnessFingerprint,f.acceptance.acceptanceSha256);});
for(const [name,change] of [['missing original file',f=>f.acceptance.ordinaryFiles.pop()],['missing engine',f=>f.acceptance.browserFiles=f.acceptance.browserFiles.filter(r=>r.engine!=='webkit')],['unrepaired file',f=>f.acceptance.ordinaryFiles[0].state='FAILED'],['compiler from old source',f=>f.acceptance.wholeCompiler.candidate=EMAIL.original],['hidden original failure',f=>f.acceptance.originalRun.conclusion='success'],['fake full pass',f=>f.acceptance.fullGatePassCreated=true],['changed actual baseline',f=>f.evidence.deploymentBaseline=EMAIL.staging],['different build artifact',f=>f.evidence.artifact.id++],['untrusted build',f=>f.snapshot.run.head_sha=EMAIL.controller],['skipped build',f=>f.snapshot.jobs.find(j=>j.name==='build').conclusion='skipped'],['expired evidence',f=>f.now+=86400001]])test('refuses '+name,()=>{const f=fixture();change(f);const {acceptanceSha256,...body}=f.acceptance;f.acceptance.acceptanceSha256=installHash(installJson(body));assert.throws(()=>createEmailInstallGrant(f));});
test('build-only packet never supplies test coverage and rejects another source',()=>{const f=fixture(),expected={candidate:EMAIL.candidate,controller:EMAIL.buildController,runId:EMAIL.buildRun};assert.equal(inspectEmailRepairBuildOnlySnapshot({...f.snapshot,expected,now:f.now}).fullGatePassCreated,false);assert.throws(()=>inspectEmailRepairBuildOnlySnapshot({...f.snapshot,expected:{...expected,candidate:EMAIL.bonus},now:f.now}));});
